output_text:
[
  {
    "id": "must_take_cart",
    "text": "A shopper is obliged to take the available cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "cart_stand": "at(1,5)",
        "cart_available_at_stand": "cartAt(1,5)"
      },
      "events": {
        "take_cart_from_stand": {
          "pre": {
            "and": [
              "cart_stand",
              "cart_available_at_stand",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart_from_stand"
    }
  },
  {
    "id": "no_pickup_without_cart",
    "text": "A shopper is forbidden to pick up shelf items unless they currently have the cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        },
        "item_pickup_with_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is forbidden to carry merchandise by hand rather than using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "properly_using_cart": {
          "and": [
            "hasCart",
            {
              "not": "handFull"
            }
          ]
        }
      },
      "events": {
        "become_hand_full": {
          "pre": "PICKUP_ITEM",
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_before_exit",
    "text": "After taking a cart, the shopper is obliged to return it to the cart-return area before leaving the store.",
    "abstraction": {
      "state_properties": {
        "cart_return_area": "at(0,1)",
        "cart_parked_in_return_area": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart": {
          "pre": {
            "and": [
              "cart_return_area",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_area"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart"
    }
  },
  {
    "id": "leave_cart_only_at_return",
    "text": "A shopper is forbidden to leave a cart anywhere except the designated return cell.",
    "abstraction": {
      "state_properties": {
        "designated_cart_return": "at(0,1)",
        "not_at_designated_cart_return": {
          "not": "designated_cart_return"
        }
      },
      "events": {
        "abandon_cart_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_designated_cart_return"
            ]
          },
          "post": null
        },
        "proper_cart_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "designated_cart_return"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "abandon_cart_elsewhere"
    }
  },
  {
    "id": "no_cart_in_exit_corridor",
    "text": "Shopping carts are forbidden in the front exit corridor east of the cart stand.",
    "abstraction": {
      "state_properties": {
        "front_exit_corridor": {
          "or": [
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_front_exit_corridor": {
          "and": [
            "hasCart",
            "front_exit_corridor"
          ]
        }
      },
      "events": {
        "push_cart_into_exit_corridor": {
          "pre": {
            "and": [
              "hasCart",
              "E",
              {
                "or": [
                  "at(1,5)",
                  "at(2,5)",
                  "at(3,5)",
                  "at(4,5)",
                  "at(5,5)",
                  "at(6,5)",
                  "at(7,5)",
                  "at(8,5)"
                ]
              }
            ]
          },
          "post": "front_exit_corridor"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_front_exit_corridor"
    }
  },
  {
    "id": "cart_one_way_no_south_middle",
    "text": "While pushing a cart in the middle shelf aisle, the shopper is forbidden to turn south toward the front aisle.",
    "abstraction": {
      "state_properties": {
        "middle_shelf_aisle": {
          "or": [
            "at(3,2)",
            "at(4,2)",
            "at(5,2)",
            "at(6,2)"
          ]
        },
        "pushing_cart_in_middle_shelf_aisle": {
          "and": [
            "hasCart",
            "middle_shelf_aisle"
          ]
        }
      },
      "events": {
        "south_turn_with_cart_from_middle_aisle": {
          "pre": {
            "and": [
              "pushing_cart_in_middle_shelf_aisle",
              "S"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "south_turn_with_cart_from_middle_aisle"
    }
  },
  {
    "id": "park_immediately_at_return",
    "text": "When the shopper reaches the cart-return area while still holding the cart, they are obliged to leave the cart there immediately.",
    "abstraction": {
      "state_properties": {
        "cart_return_area": "at(0,1)",
        "at_return_with_cart": {
          "and": [
            "cart_return_area",
            "hasCart"
          ]
        },
        "cart_parked_at_return": "cartAt(0,1)"
      },
      "events": {
        "park_cart_now": {
          "pre": {
            "and": [
              "at_return_with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "at_return_with_cart",
      "discharge": "park_cart_now"
    }
  }
]
